CREATE OR REPLACE FUNCTION "public"."accept_team_invite"("p_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invite_id uuid;
  v_client_id uuid;
  v_client_name text;
  v_role text;
  v_user_id uuid;
  v_existing_member uuid;
BEGIN
  -- Obtener el ID del usuario autenticado
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  -- Buscar la invitación pendiente
  SELECT cm.id, cm.client_id, cm.role, c.name
  INTO v_invite_id, v_client_id, v_role, v_client_name
  FROM client_members cm
  JOIN clients c ON c.id = cm.client_id
  WHERE cm.invite_token = p_token
    AND cm.status = 'pending'
  LIMIT 1;

  -- Validar que la invitación existe
  IF v_invite_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'invalid',
      'message', 'Esta invitación no es válida o ya fue usada'
    );
  END IF;

  -- Verificar si el usuario ya es miembro activo de este cliente
  SELECT id INTO v_existing_member
  FROM client_members
  WHERE client_id = v_client_id
    AND auth_user_id = v_user_id
    AND status = 'active'
  LIMIT 1;

  IF v_existing_member IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'already_member',
      'message', 'Ya eres miembro de este equipo'
    );
  END IF;

  -- Aceptar la invitación
  UPDATE client_members
  SET
    auth_user_id = v_user_id,
    status = 'active',
    accepted_at = NOW()
  WHERE id = v_invite_id;

  -- Retornar éxito con datos del cliente
  RETURN jsonb_build_object(
    'success', true,
    'client_name', v_client_name,
    'role', v_role
  );
END;
$$;


ALTER FUNCTION "public"."accept_team_invite"("p_token" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_team_invite"("p_token" "uuid") IS 'Acepta una invitación de equipo pendiente y asocia la membresía al usuario autenticado';



CREATE OR REPLACE FUNCTION "public"."cancel_expired_payment_links"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cancelled_count integer;
BEGIN
  -- Cancelar órdenes con payment_status = 'pending' cuyo link expiró hace más de 24 horas
  WITH cancelled_orders AS (
    UPDATE public.service_orders
    SET
      payment_status = 'cancelled',
      cancelled_at = NOW(),
      cancel_reason = 'Payment link expired'
    WHERE payment_status = 'pending'
      AND payment_link_expires_at IS NOT NULL
      AND payment_link_expires_at < NOW() - INTERVAL '24 hours'
      AND cancelled_at IS NULL
    RETURNING id
  )
  SELECT COUNT(*) INTO v_cancelled_count FROM cancelled_orders;

  RETURN v_cancelled_count;
END;
$$;


ALTER FUNCTION "public"."cancel_expired_payment_links"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_expired_payment_links"() IS 'Cancela automáticamente órdenes con links de pago expirados hace más de 24 horas';



CREATE OR REPLACE FUNCTION "public"."cancel_expired_token_payments"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cancelled_count integer;
BEGIN
  -- Cancelar transacciones con payment_status = 'pending' que llevan más de 1 hora
  WITH cancelled_txs AS (
    UPDATE public.token_transactions
    SET
      payment_status = 'cancelled',
      cancelled_at = NOW(),
      cancel_reason = 'Payment timeout (1 hour expired)'
    WHERE payment_status = 'pending'
      AND type = 'purchase'
      AND payment_expires_at IS NOT NULL
      AND payment_expires_at < NOW()
      AND cancelled_at IS NULL
    RETURNING id
  )
  SELECT COUNT(*) INTO v_cancelled_count FROM cancelled_txs;

  RETURN v_cancelled_count;
END;
$$;


ALTER FUNCTION "public"."cancel_expired_token_payments"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_expired_token_payments"() IS 'Cancela automáticamente transacciones pendientes que llevan más de 1 hora. Se ejecuta cada hora via pg_cron o N8N.';



CREATE OR REPLACE FUNCTION "public"."check_whatsapp_lines_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_current_count integer;
  v_max_allowed integer;
BEGIN
  -- Contar líneas actuales del cliente
  SELECT COUNT(*) INTO v_current_count
  FROM whatsapp_lines
  WHERE client_id = NEW.client_id;

  -- Obtener límite del cliente
  SELECT max_whatsapp_lines INTO v_max_allowed
  FROM clients
  WHERE id = NEW.client_id;

  -- Validar
  IF v_current_count >= v_max_allowed THEN
    RAISE EXCEPTION 'Límite de % líneas de WhatsApp alcanzado para este cliente', v_max_allowed;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_whatsapp_lines_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_default_permissions"("p_member_id" "uuid", "p_role" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  all_sections dashboard_section[] := ARRAY[
    'overview', 'agents', 'wa-interactions', 'wa-connections',
    'usage', 'tokens', 'account'
  ]::dashboard_section[];
  all_perms section_permission[] := ARRAY['view','edit','create','delete']::section_permission[];
  view_only  section_permission[] := ARRAY['view']::section_permission[];
  s dashboard_section;
BEGIN
  FOREACH s IN ARRAY all_sections LOOP
    INSERT INTO member_permissions (member_id, section, permissions)
    VALUES (
      p_member_id,
      s,
      CASE WHEN p_role = 'admin' THEN all_perms ELSE view_only END
    )
    ON CONFLICT (member_id, section) DO NOTHING;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."create_default_permissions"("p_member_id" "uuid", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_default_permissions_for_role"("p_member_id" "uuid", "p_role" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Billing: solo tokens (comprar/ver) y account (ver su cuenta)
  IF p_role = 'billing' THEN
    INSERT INTO public.member_permissions (member_id, section, permissions) VALUES
      (p_member_id, 'tokens', ARRAY['view', 'edit']::section_permission[]),
      (p_member_id, 'account', ARRAY['view']::section_permission[])
    ON CONFLICT (member_id, section) DO NOTHING;

  -- Viewer: solo lectura en todo
  ELSIF p_role = 'viewer' THEN
    INSERT INTO public.member_permissions (member_id, section, permissions) VALUES
      (p_member_id, 'overview', ARRAY['view']::section_permission[]),
      (p_member_id, 'agents', ARRAY['view']::section_permission[]),
      (p_member_id, 'wa-interactions', ARRAY['view']::section_permission[]),
      (p_member_id, 'wa-connections', ARRAY['view']::section_permission[]),
      (p_member_id, 'usage', ARRAY['view']::section_permission[]),
      (p_member_id, 'tokens', ARRAY['view']::section_permission[]),
      (p_member_id, 'account', ARRAY['view']::section_permission[])
    ON CONFLICT (member_id, section) DO NOTHING;

  -- Agent Manager: gestión completa de agentes
  ELSIF p_role = 'agent-manager' THEN
    INSERT INTO public.member_permissions (member_id, section, permissions) VALUES
      (p_member_id, 'overview', ARRAY['view']::section_permission[]),
      (p_member_id, 'agents', ARRAY['view', 'edit', 'create', 'delete']::section_permission[]),
      (p_member_id, 'wa-interactions', ARRAY['view']::section_permission[]),
      (p_member_id, 'wa-connections', ARRAY['view']::section_permission[]),
      (p_member_id, 'usage', ARRAY['view']::section_permission[]),
      (p_member_id, 'account', ARRAY['view']::section_permission[])
    ON CONFLICT (member_id, section) DO NOTHING;
  END IF;
END;
$$;


ALTER FUNCTION "public"."create_default_permissions_for_role"("p_member_id" "uuid", "p_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_default_permissions_for_role"("p_member_id" "uuid", "p_role" "text") IS 'Crea permisos por defecto según el rol asignado: billing (solo tokens y account), viewer (solo lectura en todo), agent-manager (gestión de agentes)';



CREATE OR REPLACE FUNCTION "public"."get_client_members_with_email"("p_client_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "auth_user_id" "uuid", "role" "text", "status" "text", "email" "text", "full_name" "text", "invite_token" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_client_id uuid;
  v_is_super_admin boolean;
BEGIN
  -- Si no se proporciona client_id, obtener el del usuario autenticado
  IF p_client_id IS NULL THEN
    SELECT cm.client_id INTO v_client_id
    FROM public.client_members cm
    WHERE cm.auth_user_id = auth.uid()
      AND cm.status = 'active'
    LIMIT 1;
  ELSE
    -- Si se proporciona client_id, verificar que el usuario tenga acceso
    v_client_id := p_client_id;

    -- Verificar si es super admin
    SELECT public.is_super_admin() INTO v_is_super_admin;

    -- Si no es super admin, verificar que sea miembro del cliente
    IF NOT v_is_super_admin THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.client_members cm2
        WHERE cm2.auth_user_id = auth.uid()
          AND cm2.client_id = v_client_id
          AND cm2.status = 'active'
      ) THEN
        -- No tiene acceso a este cliente
        RETURN;
      END IF;
    END IF;
  END IF;

  IF v_client_id IS NULL THEN
    RETURN;
  END IF;

  -- Retornar miembros del cliente con sus emails desde auth.users
  RETURN QUERY
  SELECT
    cm.id,
    cm.auth_user_id,
    cm.role::text,
    cm.status::text,
    COALESCE(u.email::text, cm.invite_email::text) AS email,
    COALESCE(u.raw_user_meta_data->>'name', u.email, cm.invite_email)::text AS full_name,
    cm.invite_token
  FROM public.client_members cm
  LEFT JOIN auth.users u ON u.id = cm.auth_user_id
  WHERE cm.client_id = v_client_id
    AND (cm.status = 'active' OR cm.status = 'pending')
  ORDER BY cm.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_client_members_with_email"("p_client_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_client_members_with_email"("p_client_id" "uuid") IS 'Retorna miembros de un cliente con sus emails desde auth.users. Soporta impersonalización de super admin.';



