CREATE OR REPLACE FUNCTION "public"."sync_super_admin_to_metadata"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_is_super boolean;
BEGIN
  -- Determinar si el usuario es super_admin
  v_is_super := (NEW.role = 'super_admin' AND NEW.status = 'active');

  -- Actualizar metadata en auth.users
  UPDATE auth.users
  SET raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb) ||
      jsonb_build_object('is_super_admin', v_is_super)
  WHERE id = NEW.auth_user_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_super_admin_to_metadata"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_super_admin_to_metadata"() IS 'Sincroniza el rol super_admin al user metadata para evitar queries recursivos en RLS';



