CREATE OR REPLACE VIEW "public"."token_profitability" AS
 SELECT "client_id",
    "agent_id",
    "date"("created_at") AS "date",
    "count"(*) AS "transactions",
    "sum"("abs"("tokens_real")) AS "total_tokens_real",
    "sum"("abs"("tokens_charged")) AS "total_tokens_charged",
    "sum"(("abs"("tokens_charged") - "abs"("tokens_real"))) AS "total_profit_tokens",
        CASE
            WHEN ("sum"("abs"("tokens_real")) > (0)::numeric) THEN "round"((("sum"(("abs"("tokens_charged") - "abs"("tokens_real"))) / "sum"("abs"("tokens_real"))) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "profit_percentage"
   FROM "public"."token_transactions"
  WHERE ((("type")::"text" = 'consumption'::"text") AND ("tokens_real" IS NOT NULL) AND ("tokens_charged" IS NOT NULL))
  GROUP BY "client_id", "agent_id", ("date"("created_at"))
  ORDER BY ("date"("created_at")) DESC;


ALTER VIEW "public"."token_profitability" OWNER TO "postgres";


COMMENT ON VIEW "public"."token_profitability" IS 'Vista de rentabilidad: compara tokens reales vs cobrados por día';



