CREATE POLICY "users_can_view_order_comments" ON "public"."service_comments" FOR SELECT USING (((("service_order_id" IN ( SELECT "service_orders"."id"
   FROM "public"."service_orders"
  WHERE ("service_orders"."client_id" IN ( SELECT "public"."get_my_client_ids"() AS "get_my_client_ids")))) AND (("is_internal" = false) OR "public"."is_super_admin"())) OR "public"."is_super_admin"()));



CREATE POLICY "users_can_view_order_deliverables" ON "public"."service_deliverables" FOR SELECT USING ((("service_order_id" IN ( SELECT "service_orders"."id"
   FROM "public"."service_orders"
  WHERE ("service_orders"."client_id" IN ( SELECT "public"."get_my_client_ids"() AS "get_my_client_ids")))) OR "public"."is_super_admin"()));



CREATE POLICY "view permissions" ON "public"."member_permissions" FOR SELECT TO "authenticated" USING (("public"."is_super_admin"() OR ("member_id" IN ( SELECT "cm"."id"
   FROM "public"."client_members" "cm"
  WHERE ("cm"."client_id" IN ( SELECT "public"."get_my_client_ids"() AS "get_my_client_ids")))) OR ("member_id" IN ( SELECT "client_members"."id"
   FROM "public"."client_members"
  WHERE ("client_members"."auth_user_id" = "auth"."uid"())))));



